import{_ as e,o as r,c as a,a5 as d}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"Grammar Evidence Card: From Rule Recognition to Real Expression","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/grammar-evidence.en.md","filePath":"public/downloads/worksheets/grammar-evidence.en.md","lastUpdated":1795488252000}'),n={name:"public/downloads/worksheets/grammar-evidence.en.md"};function i(o,t,l,s,h,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="grammar-evidence-card-from-rule-recognition-to-real-expression" tabindex="-1">Grammar Evidence Card: From Rule Recognition to Real Expression <a class="header-anchor" href="#grammar-evidence-card-from-rule-recognition-to-real-expression" aria-label="Permalink to &quot;Grammar Evidence Card: From Rule Recognition to Real Expression&quot;">​</a></h1><p>Track one high-impact structure per card. Copy it into a private note and keep the original sentence plus revision reason. Do not record sensitive customer, company, school, medical, or third-party material; use synthetic facts or a minimised excerpt.</p><h2 id="_1-define-the-real-task" tabindex="-1">1. Define the Real Task <a class="header-anchor" href="#_1-define-the-real-task" aria-label="Permalink to &quot;1. Define the Real Task&quot;">​</a></h2><p>Date:<br> Situation: email / explanation / dialogue / retelling / interview / other<br> Audience:<br> What the task must let the other person understand or do:<br> Time, tool, and length restrictions:<br> Raw sample location:</p><h2 id="_2-locate-one-structural-problem" tabindex="-1">2. Locate One Structural Problem <a class="header-anchor" href="#_2-locate-one-structural-problem" aria-label="Permalink to &quot;2. Locate One Structural Problem&quot;">​</a></h2><p>My original sentence/segment:<br> Most likely interpretation:<br> Meaning I intended:<br> Impact: meaning-changing / task-blocking / recurring / register mismatch / low-impact<br> One structure tracked in this cycle:</p><table tabindex="0"><thead><tr><th>Sample</th><th>Structural choice</th><th>Real relationship expressed</th><th>Fits the task?</th></tr></thead><tbody><tr><td>Original</td><td></td><td></td><td></td></tr><tr><td>Contrast A</td><td></td><td></td><td></td></tr><tr><td>Contrast B</td><td></td><td></td><td></td></tr></tbody></table><h2 id="_3-write-a-meaning-contrast-card" tabindex="-1">3. Write a Meaning Contrast Card <a class="header-anchor" href="#_3-write-a-meaning-contrast-card" aria-label="Permalink to &quot;3. Write a Meaning Contrast Card&quot;">​</a></h2><p>Meaning I need to express:<br> Forms I confuse:<br> Example and source from reliable material:<br> One-sentence explanation in my words:<br> Counterexample or boundary:</p><p>The explanation should answer why the form matches the fact rather than copy only a terminology definition.</p><h2 id="_4-preserve-revision-and-reason" tabindex="-1">4. Preserve Revision and Reason <a class="header-anchor" href="#_4-preserve-revision-and-reason" aria-label="Permalink to &quot;4. Preserve Revision and Reason&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Condition</th><th>Sentence/output location</th><th>What changed</th><th>Why</th></tr></thead><tbody><tr><td>First</td><td>No prompt</td><td></td><td></td><td></td></tr><tr><td>Revised</td><td>Explanation/feedback seen</td><td></td><td></td><td></td></tr><tr><td>Independent repeat</td><td>Material closed</td><td></td><td></td><td></td></tr></tbody></table><p>How the other person understood the revision:<br> Problem still affecting the task:<br> Suggested style change I rejected:</p><h2 id="_5-retrieve-across-four-skills" tabindex="-1">5. Retrieve across Four Skills <a class="header-anchor" href="#_5-retrieve-across-four-skills" aria-label="Permalink to &quot;5. Retrieve across Four Skills&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Small task</th><th>Result</th><th>Evidence</th></tr></thead><tbody><tr><td>Listening</td><td>Hear the relationship carried by the structure</td><td></td><td></td></tr><tr><td>Reading</td><td>Mark scope, reference, or logical connection</td><td></td><td></td></tr><tr><td>Speaking</td><td>Use under time pressure and repair after error</td><td></td><td></td></tr><tr><td>Writing</td><td>Compare how two versions change reader understanding</td><td></td><td></td></tr></tbody></table><p>You do not need all four every cycle. Keep at least one input observation and one active output.</p><h2 id="_6-ai-and-feedback-record" tabindex="-1">6. AI and Feedback Record <a class="header-anchor" href="#_6-ai-and-feedback-record" aria-label="Permalink to &quot;6. AI and Feedback Record&quot;">​</a></h2><p>Tool/reviewer and date:<br> Problem observed:<br> Explanation given:<br> Did it separate error, ambiguity, register, and style?<br> Dictionary, corpus, teacher, or reader check:<br> What I accepted/rejected, and why:</p><h2 id="_7-delayed-retest" tabindex="-1">7. Delayed Retest <a class="header-anchor" href="#_7-delayed-retest" aria-label="Permalink to &quot;7. Delayed Retest&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time point</th><th>Prompt condition</th><th>New task</th><th>Independent choice</th><th>Result</th></tr></thead><tbody><tr><td>Day 1</td><td>Original task, no prompt</td><td></td><td></td><td></td></tr><tr><td>Days 3–7</td><td>Rule and old answer removed</td><td>Parallel topic</td><td></td><td></td></tr><tr><td>Day 14</td><td>New audience or time pressure</td><td>Transfer task</td><td></td><td></td></tr></tbody></table><p>Judgment retained on day seven:<br> Error that returned:<br> Where transfer failed:</p><h2 id="_8-score-and-decide" tabindex="-1">8. Score and Decide <a class="header-anchor" href="#_8-score-and-decide" aria-label="Permalink to &quot;8. Score and Decide&quot;">​</a></h2><p>Score 0–2: <code>0=not completed</code>, <code>1=prompt-dependent or unstable</code>, <code>2=completed under the current condition</code>.</p><table tabindex="0"><thead><tr><th>Item</th><th style="text-align:right;">Day 1</th><th style="text-align:right;">Day 7</th><th style="text-align:right;">Day 14</th><th>Evidence reason</th></tr></thead><tbody><tr><td>Explain form–meaning difference</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Recognise it in a new sentence</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Retrieve it in output</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Self-repair after error</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Stop repeatedly changing key meaning</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>Current evidence supports: continue same structure / add variation / move to another problem / pause<br> Evidence:<br> Conclusion I still cannot draw:<br> Smallest next task:<br> Next review date:</p><p>Related chapters: <a href="https://byoungd.github.io/up/en/threads/part-1/grammar" target="_blank" rel="noreferrer">Grammar: Let Structure Serve Meaning</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/1-understanding" target="_blank" rel="noreferrer">Learning Principles</a> | <a href="https://byoungd.github.io/up/en/templates/evidence-chain" target="_blank" rel="noreferrer">Evidence Chain Template</a></p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/grammar-evidence" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-09-02. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',28)])])}const g=e(n,[["render",i]]);export{u as __pageData,g as default};
